<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT r.*,p.name AS product_name,u.first_name,u.last_name FROM product_reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id WHERE r.vendor_id=:vendor ORDER BY r.created_at DESC');$stmt->execute(['vendor'=>$vendorId]);json_response(200,['success'=>true,'reviews'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$id=trim((string)($body['review_id']??''));$reply=trim((string)($body['reply']??''));if(mb_strlen($reply)<10||mb_strlen($reply)>2000)json_response(422,['success'=>false,'message'=>'Reply must be between 10 and 2000 characters.']);$stmt=$db->prepare('UPDATE product_reviews SET vendor_reply=:reply,replied_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE id=:id AND vendor_id=:vendor AND status="published"');$stmt->execute(['reply'=>$reply,'id'=>$id,'vendor'=>$vendorId]);if(!$stmt->rowCount())json_response(404,['success'=>false,'message'=>'Review not found.']);json_response(200,['success'=>true,'message'=>'Reply published.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
